 public static void Validate(ContractWorld w,ContractWorld? prior){if(w.Crafts==null){Need(prior?.Crafts==null,"職人・交易の台帳が消えています");return;}Need(NewGameWork.Enabled(w)&&w.Crafts.Schema==1&&w.Crafts.Policy==Policy&&(Entries(w).Length>0||LiveTerritory.Enabled(w)),"職人・交易の保存形式が不正です");if(prior?.Crafts!=null)Need(ContractJson.CanonicalHash(Entries(w).Take(prior.Crafts.Entries.Length).ToArray())==ContractJson.CanonicalHash(prior.Crafts.Entries),"過去の技術・交易原本が変わっています");long rev=0,at=0;var ids=new HashSet<EntityId>();var prefixEntries=new List<CraftEntry>();foreach(var e in Entries(w)){Need(e.Revision>=rev&&e.Revision<=w.CommitSequence&&e.At>=at&&e.At<=w.ElapsedSeconds&&ids.Add(e.Input.Id),"職人・交易の順序が不正です");var prefix=w.ForkTransportLocation();prefix.ElapsedSeconds=e.At;prefix.Crafts=w.Crafts with{Entries=prefixEntries.ToArray()};var expected=Make(prefix,e.Input,e.Actor,e.At,e.Revision);Need(ContractJson.CanonicalHash(e)==ContractJson.CanonicalHash(expected),"当時の職人・原料・資金・船と実処分が違います");prefixEntries.Add(e);rev=e.Revision;at=e.At;}foreach(var site in Entries(w).Select(e=>e.Input.Site).Distinct()){Need(MerchantCash(w,site)>=0&&RawGoods.All(k=>MerchantStock(w,site,k)>=0),"商人の実物・銭が不足しています");foreach(var owner in Entries(w).Where(e=>e.Input.Site==site).Select(e=>e.Input.Owner).Distinct())foreach(var good in RawGoods.Concat(Recipes.Select(r=>r.Good)))Need(Stock(w,owner,site,good)>=0,"実在しない原料・製品を使っています");}}
