public sealed partial class WorldSession
{
 public CommandResult ManageCraft(CraftInput i,long revision){lock(gate){var old=CraftTrade.Entries(state).SingleOrDefault(e=>e.Input.Id==i.Id);if(old!=null)return new(old.Input==i?ResultCode.AlreadyAccepted:ResultCode.IdPayloadConflict,i.Id,state.CommitSequence,"受付済みです");if(revision!=state.CommitSequence)return new(ResultCode.StateChanged,i.Id,state.CommitSequence,"表示を更新してください");if(i.Action==CraftAction.ReturnVoyage||NewGameWork.OwnIdUsed(state,i.Id)||state.Requests.Any(q=>q.Id==i.Id))return new(ResultCode.NotAvailable,i.Id,state.CommitSequence,"同じ原本か、船の実帰港を確認してください");try{Change(w=>CraftTrade.Execute(w,i,w.PlayerControl));return new(ResultCode.Accepted,i.Id,state.CommitSequence,"条件・実物・工期と帰港を分けて記録しました");}catch(Exception e)when(e is InvalidDataException or InvalidOperationException or ArgumentException or OverflowException){return new(ResultCode.NotAvailable,i.Id,state.CommitSequence,e.Message);}}}
}
